package com.example.ledger.io;

import com.example.ledger.Entry;
import com.example.ledger.Ledger;
import com.example.ledger.Transaction;
import java.util.ArrayList;
import java.util.List;

/**
 * Exports two-entry transfers in the importer's format
 * ({@code date,description,from,to,amount,currency}) so finance can open them in a
 * spreadsheet or re-import them with {@link CsvImporter}. Transactions with more than
 * two entries are skipped.
 */
public final class CsvExporter {
    private CsvExporter() {
    }

    public static List<String> exportLines(Ledger ledger) {
        List<String> lines = new ArrayList<>();
        lines.add(String.join(",", CsvImporter.HEADER));
        for (Transaction tx : ledger.journal()) {
            if (tx.entries().size() != 2) {
                continue;
            }
            Entry first = tx.entries().get(0);
            Entry second = tx.entries().get(1);
            Entry from = first.amount().isNegative() ? first : second;
            Entry to = from == first ? second : first;
            lines.add(String.join(",",
                    tx.date().toString(),
                    CsvParser.quote(tx.description()),
                    from.accountId(),
                    to.accountId(),
                    to.amount().toDecimal().toPlainString(),
                    to.amount().currency()));
        }
        return lines;
    }

    public static String export(Ledger ledger) {
        return String.join("\n", exportLines(ledger)) + "\n";
    }
}

